def find_pattern(n, m, filenames, indices_to_delete):
    # Convert indices to zero-based for easier manipulation
    indices_to_delete = [i - 1 for i in indices_to_delete]

    # Initialize the pattern with the first file to be deleted
    pattern = list(filenames[indices_to_delete[0]])

    # Iterate over the rest of the files to be deleted
    for index in indices_to_delete[1:]:
        current_filename = filenames[index]
        for i in range(len(pattern)):
            if pattern[i] != current_filename[i]:
                pattern[i] = '?'

    # Check if the pattern matches exactly m files
    def matches(filename, pattern):
        if len(filename) != len(pattern):
            return False
        for f_char, p_char in zip(filename, pattern):
            if p_char != '?' and f_char != p_char:
                return False
        return True

    count_matching_files = sum(1 for filename in filenames if matches(filename, pattern))

    if count_matching_files == m:
        return "Yes", "".join(pattern)
    else:
        return "No", ""

